<script setup lang="ts">
const props=defineProps<{goodsId?:number;companyId?:number}>()
const {t}=useI18n(),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),busy=ref(false),error=ref(''),category=ref(''),newCategory=ref('')
const editable=computed(()=>staff.hasPermission(props.goodsId?'goods_edit':'company_edit'))
const url=computed(()=>props.goodsId?`/api/warehouse/goods/${props.goodsId}/lot-rules`:`/api/warehouse/company/${props.companyId}/lot-rules`)
const keys=['mode','source','shelf_life_days','warning_days','receive_days','ship_days','strategy','allow_unassigned']
const enums:Record<string,string[]>={mode:['none','lot','expiry'],source:['manual','auto'],strategy:['fifo','fefo'],allow_unassigned:['true','false']}
const values=computed<Record<string,any>>(()=>props.goodsId?data.value?.overrides||{}:category.value?data.value?.categories[category.value]||{}:data.value?.defaults||{})
const valueOf=(key:string)=>Object.hasOwn(values.value,key)?String(values.value[key]??''):'inherit'
const change=(key:string,value:unknown)=>{if(value==='inherit'){delete values.value[key];return}values.value[key]=key==='allow_unassigned'?value==='true':enums[key]?value:value===''||value==null?null:Number(value)}
const snapshot=()=>JSON.stringify(props.goodsId?data.value?.overrides:{defaults:data.value?.defaults,categories:data.value?.categories})
const original=ref('')
const dirty=computed(()=>editable.value&&!!data.value&&!!original.value&&(snapshot()!==original.value||!!newCategory.value.trim()))
useUnsavedForm(()=>dirty.value,()=>busy.value)
let generation=0,confirming=false
const retry=async()=>{if(busy.value||confirming)return;confirming=true;try{if(!dirty.value||await wConfirm({title:t('unsaved-form.title'),message:t('unsaved-form.message'),confirmText:t('unsaved-form.leave'),cancelText:t('unsaved-form.stay')})){newCategory.value='';await load()}}finally{confirming=false}}
const load=async()=>{const seq=++generation;busy.value=true;error.value='';data.value=null;const result=await httpRequest<any>(url.value,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;original.value=result?snapshot():'';if(category.value&&!result?.categories?.[category.value])category.value='';busy.value=false}}
const save=async()=>{if(busy.value||!editable.value||!data.value)return;busy.value=true;error.value='';const body=props.goodsId?{revision:data.value.revision,overrides:data.value.overrides}:{revision:data.value.revision,defaults:data.value.defaults,categories:data.value.categories};try{const result=await httpRequest<any>(url.value,{method:'PUT',body,onError:e=>error.value=bizErrorMessage(e)});if(result){data.value=result;original.value=snapshot();showToast(t('action-results.success'),'success')}}finally{busy.value=false}}
const addCategory=()=>{const key=newCategory.value.trim();if(!key)return;if(!data.value.categories[key])data.value.categories[key]={};category.value=key;newCategory.value=''}
watch(url,()=>{category.value='';load()},{immediate:true});onBeforeUnmount(()=>generation++)
</script>
<template><section class="lot-rules"><h2>{{t('lot-rules.title')}}</h2><p>{{t('lot-rules.help')}}</p><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton :disabled="busy" @click="retry">{{t('dn.list.retry')}}</WButton></template></WAlert><WEmptyState v-if="busy&&!data" :title="t('common.status.loading')"/><template v-if="data"><div v-if="!goodsId" class="categories"><WSelect v-model="category" :options="[{value:'',label:t('lot-rules.company')},...Object.keys(data.categories).map(value=>({value,label:value}))]" :disabled="busy"/><WInput v-if="editable" v-model="newCategory" :placeholder="t('goods.fields.category')" :aria-label="t('goods.fields.category')" maxlength="100" :disabled="busy"/><WButton v-if="editable" :disabled="busy||!newCategory.trim()" @click="addCategory">{{t('lot-rules.add-category')}}</WButton><WButton v-if="editable&&category" :disabled="busy" @click="delete data.categories[category];category=''">{{t('button.delete')}}</WButton></div><WFormGrid><WField v-for="key in keys" :key="key" :span="6" :label="t('lot-rules.'+key)" :hint="goodsId?t('lot-rules.effective')+': '+(enums[key]?t('lot-rules.'+String(data.values[key])):(data.values[key]??'—'))+' · '+t('lot-rules.'+data.sources[key]):undefined"><WSelect v-if="enums[key]" :model-value="valueOf(key)" :options="[...(goodsId||category?[{value:'inherit',label:t('lot-rules.inherit')}]:[]),...enums[key]!.map(value=>({value,label:t('lot-rules.'+value)}))]" :disabled="busy||!editable" @update:model-value="change(key,$event)"/><div v-else class="number"><WInput :model-value="values[key]??''" type="number" min="0" max="36500" step="1" :disabled="busy||!editable" @update:model-value="change(key,$event)"/><WButton v-if="(goodsId||category)&&editable" size="sm" :disabled="busy" @click="change(key,'inherit')">{{t('lot-rules.inherit')}}</WButton></div></WField></WFormGrid><footer><WButton v-if="editable" variant="primary" :loading="busy" @click="save">{{t('button.save')}}</WButton></footer></template></section></template>
<style scoped>.lot-rules{padding:20px}.lot-rules h2{font-size:16px;margin:0 0 8px}.lot-rules p{font-size:13px;color:var(--w-text-3);margin:0 0 16px}.categories,.number{display:flex;gap:8px;align-items:center}.categories{flex-wrap:wrap;margin-bottom:20px}.categories>*{max-width:240px}.number>.w-input{min-width:0;flex:1}.number>.w-btn{flex:none}footer{display:flex;justify-content:flex-end;margin-top:16px}</style>
